sys_script_include.script:
function DevToolsGetParentRecord(grRecord)
{
	var GetRecord = x_snc_devtools.GetRecord;
	var strTable = grRecord.getRecordClassName();

	if (strTable == 'x_snc_stores_hours_rule_set')
	{
		return GetRecord('x_snc_stores_store',grRecord.store);
	}

	if (strTable == 'x_snc_stores_hours_rule')
	{
		return GetRecord('x_snc_stores_hours_rule_set',grRecord.hours_rule_set);
	}

	return false;
}
